 color:{light:{canvas:'#F6F7F5',surface:'#FFFFFF',surfaceSubtle:'#F0F3EF',text:'#1B2B27',textSecondary:'#53645E',textMuted:'#5D6D64',border:'#DCE3DC',borderStrong:'#7E9184',brand:'#145F50',onBrand:'#FFFFFF',brandSoft:'#E9F2ED',success:'#216447',successSoft:'#EAF5EE',warning:'#8B4B0B',warningSoft:'#FFF3DF',danger:'#B03939',dangerSoft:'#FFF0EF',info:'#305EB1',infoSoft:'#EDF2FC',focus:'#2563B0'},dark:{canvas:'#111816',surface:'#19221E',surfaceSubtle:'#202C25',text:'#E8EEE8',textSecondary:'#B3C1B6',textMuted:'#9CAE9F',border:'#34473B',borderStrong:'#697E70',brand:'#9CD7B5',onBrand:'#13291D',brandSoft:'#263E30',success:'#9ED9B6',successSoft:'#233E2E',warning:'#F0C07E',warningSoft:'#3A3021',danger:'#F2A2A0',dangerSoft:'#402A2A',info:'#ADC7FF',infoSoft:'#283549',focus:'#99BCFF'}},
