function rules(items){return `<div class="rule-list">${items.map(([h,p],i)=>`<div class="rule-item"><span class="rule-num">${String(i+1).padStart(2,'0')}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div>`}
export function designSystemPage(){const dark=document.documentElement.dataset.theme==='dark';const c=tokens.color[dark?'dark':'light'];const swatches=[['Canvas',c.canvas,t('Page background','Sayfa zemini')],['Surface',c.surface,t('Panels and inputs','Paneller ve alanlar')],['Ink',c.text,t('Primary text','Ana metin')],['Forest',c.brand,t('Primary action and selection','Ana eylem ve seçim')],['Success',c.success,t('Verified result','Doğrulanmış sonuç')],['Warning',c.warning,t('Action needed soon','Yakında işlem gerekiyor')],['Danger',c.danger,t('Failure or expired state','Hata veya süre aşımı')],['Information',c.info,t('In-progress operations','Devam eden işlemler')]];
return title(t('Design system','Tasarım sistemi'),t('A practical rulebook for every Alice screen.','Her Alice ekranı için uygulanabilir tasarım kuralları.'),btn(t('Download tokens','Token dosyasını indir'),'download-tokens','Download')+link(t('Download UI source','Arayüz kodunu indir'),'','','btn').replace('href="#/"','href="alice-design-source.zip" download'))+
`<div class="design-hero"><div><div class="eyebrow">ALICE / CLARITY — 01</div><h2>${t('Quiet confidence.<br>Visible control.','Sakin bir güven.<br>Görünür kontrol.')}</h2><p>${t('A product language for serious infrastructure work: warm neutral surfaces, a restrained forest accent and precise technical typography.','Ciddi altyapı işleri için bir ürün dili: sıcak nötr yüzeyler, ölçülü koyu yeşil vurgu ve net teknik tipografi.')}</p></div><div class="design-seal"><img src="assets/alice.svg" alt="Alice mark"></div></div>
<div class="tabs"><a href="#/design-system" class="tab ${location.hash.includes('section=components')?'':'active'}">${t('Foundations','Temeller')}</a><a href="#/design-system?section=components" class="tab ${location.hash.includes('section=components')?'active':''}">${t('Components & states','Bileşenler ve durumlar')}</a><a href="#/review" class="tab">${t('Product rationale','Ürün gerekçeleri')}</a></div>
<div class="stack">${panel(t('01 / Color with a job to do','01 / İşlevi olan renkler'),t('Semantic tokens change with the theme. Status meanings stay the same.','Anlamsal tokenlar temayla değişir. Durumların anlamları aynı kalır.'),panelBody(`<div class="swatch-grid">${swatches.map(([name,hex,desc])=>`<div class="swatch"><div class="swatch-color" style="background:${hex};color:${['Canvas','Surface'].includes(name)?c.text:['Ink','Forest','Success','Warning','Danger','Information'].includes(name)?(dark?'#13291D':'#ffffff'):'#ffffff'}">${hex}</div><div class="swatch-info"><strong>${name}</strong><p>${desc}</p></div></div>`).join('')}</div><div class="guide-callout mt24">${t('Brand green identifies an action or a selected item. “Success” is a separate semantic token and always has an explicit label. Never make “online” mean “secure”.','Marka yeşili bir eylemi veya seçimi tanımlar. “Başarılı” ayrı bir anlamsal tokendır ve her zaman açıklama taşır. “Bağlı” durumunu “güvenli” anlamında kullanmayın.')}</div>`),btn(dark?t('See light palette','Açık paleti gör'):t('See dark palette','Koyu paleti gör'),'toggle-theme',dark?'Sun':'Moon','small'))}
${panel(t('02 / Typography','02 / Tipografi'),t('Two families. Distinct responsibilities. Bundled locally for offline use.','İki aile. Farklı görevler. Çevrimdışı kullanım için yerel dosyalar.'),panelBody(`<div class="type-specimen"><div style="font-size:36px;letter-spacing:-1.5px;line-height:1.2">${t('Everything in clear view.','Her şey net bir görünümde.')}</div><div class="spec-label">Geist · 32–36 / 1.2<br>Weight 550–600 · Page title</div></div><div class="type-specimen"><div style="font-size:16px;font-weight:600">${t('The next action is easy to find.','Sonraki adımı bulmak kolay.')}</div><div class="spec-label">Geist · 16 / 1.5<br>Weight 600 · Section heading</div></div><div class="type-specimen"><div style="font-size:14px">${t('A certificate expires in 7 days. Review its locations.','Bir sertifika 7 gün içinde doluyor. Konumlarını inceleyin.')}</div><div class="spec-label">Geist · 14 / 1.5<br>Weight 400 · Body text</div></div><div class="type-specimen"><div class="mono" style="font-size:13px">SHA256:Bp7q93rW5sV9<br>nginx-prod-01 / :443</div><div class="spec-label">Geist Mono · 11–13 / 1.5<br>Weight 400 · Data & identifiers</div></div><p class="small mt24">${t('Use tabular figures for counters. Keep paragraph copy in sentence case. Reserve uppercase and wide spacing for short section labels. Turkish İ/ı, Ş/ş, Ğ/ğ, Ç/ç, Ö/ö, Ü/ü are supported by the bundled fonts.','Sayaçlarda eşit genişlikli rakamlar kullanın. Paragraflarda normal cümle düzenini koruyun. Büyük harf ve geniş harf aralığını kısa bölüm etiketlerine ayırın. Yerel fontlar İ/ı, Ş/ş, Ğ/ğ, Ç/ç, Ö/ö, Ü/ü karakterlerini destekler.')}</p>`))}
<div class="grid2">${panel(t('03 / Layout & rhythm','03 / Yerleşim ve ritim'),'',panelBody(rules([[t('4 px foundation','4 piksel temel'),t('Spacing scale: 4, 8, 12, 16, 20, 24, 32, 40. Use 20–24 px between panels and 16 px between related controls.','Boşluk ölçeği: 4, 8, 12, 16, 20, 24, 32, 40. Paneller arası 20–24, ilişkili kontroller arası 16 piksel.')],[t('Consistent application shell','Tutarlı uygulama iskeleti'),t('222 px sidebar, 65 px header, 34 px desktop canvas padding. Collapse navigation below 760 px.','222 piksel kenar çubuğu, 65 piksel üst çubuk, masaüstünde 34 piksel içerik boşluğu. 760 piksel altında menüyü daraltın.')],[t('Density is a preference','Yoğunluk bir tercihtir'),t('67 px standard table rows; 48 px compact. Preserve headers, keyboard access and horizontal scrolling on narrow screens.','Standart satır 67, kompakt satır 48 piksel. Dar ekranlarda başlıkları, klavye erişimini ve yatay kaydırmayı koruyun.')],[t('Measured shape','Ölçülü biçim'),t('6 px controls, 10 px panels, 14 px dialogs. Borders define structure; shadows are reserved for overlays.','Kontroller 6, paneller 10, pencereler 14 piksel köşe yarıçapı. Yapıyı sınırlar belirler; gölgeler üst katmanlarda kullanılır.')]])))}
${panel(t('04 / Behavior & accessibility','04 / Davranış ve erişilebilirlik'),'',panelBody(rules([[t('Visible keyboard focus','Görünür klavye odağı'),t('3 px focus outline with 3 px offset. Native dialogs contain focus; Escape closes them and focus returns to the trigger.','3 piksel odak çizgisi ve 3 piksel mesafe. Yerel dialog odağı içeride tutar; Escape kapatır ve odak açan öğeye döner.')],[t('Text carries the meaning','Anlamı metin taşır'),t('Status = label + icon + color. Required contrast: 4.5:1 for normal text, 3:1 for large text and essential controls.','Durum = etiket + simge + renk. Normal metinde 4,5:1, büyük metin ve temel kontrollerde 3:1 kontrast hedefi.')],[t('Restrained motion','Ölçülü hareket'),t('160 ms state transitions. Respect reduced-motion. No auto-playing decorations, fake live counters or flashing alerts.','160 ms durum geçişi. Azaltılmış hareket tercihini koruyun. Otomatik dekorasyon, sahte canlı sayaç veya yanıp sönen uyarı kullanmayın.')],[t('Readable localized content','Okunabilir yerelleştirme'),t('EN/TR labels, local date formatting and an explicit time zone. Fingerprints, paths and error codes are never translated.','EN/TR etiketler, yerelleştirilmiş tarih ve açık saat dilimi. Parmak izleri, yollar ve hata kodları çevrilmez.')]])))}</div>
${panel(t('05 / Components & outcome language','05 / Bileşenler ve sonuç dili'),t('Same visual grammar, different operational meaning.','Aynı görsel dil, farklı operasyon anlamları.'),panelBody(`<div class="flex wrap gap16 mb16">${btn(t('Primary action','Ana eylem'),'demo-action','Plus','primary')}${btn(t('Secondary action','İkincil eylem'),'demo-action','Download')}${btn(t('Unavailable','Kullanılamıyor'),'demo-action','','','disabled')}${badge(t('Verified','Doğrulandı'),'success','CircleCheck')}${badge(t('Expiring soon','Yakında doluyor'),'warning','Clock3')}${badge(t('Expired','Süresi doldu'),'danger','CircleAlert')}${badge(t('In progress','Devam ediyor'),'info','RotateCw')}</div>${table([t('State','Durum'),t('Required message','Zorunlu açıklama'),t('Next step','Sonraki adım')],[[t('Failed','Başarısız'),t('Explain the cause, effect and stable error code.','Nedeni, etkisini ve sabit hata kodunu açıklayın.'),t('Offer an actionable recovery path.','Uygulanabilir çözüm yolu sunun.')],[t('Rolled back','Geri alındı'),t('Say what was restored and whether the old endpoint was verified.','Neyin geri yüklendiğini ve eski uç noktanın doğrulanıp doğrulanmadığını belirtin.'),t('Inspect before retrying.','Tekrarlamadan önce inceleyin.')],[t('Recovering / unknown','Kurtarılıyor / bilinmiyor'),t('Do not claim success or “nothing changed”.','Başarı veya “hiçbir şey değişmedi” iddiasında bulunmayın.'),t('Show last known state and the next check.','Bilinen son durumu ve sonraki kontrolü gösterin.')],[t('Empty / filtered empty','Boş / filtre sonucu boş'),t('Differentiate no resources from no search matches.','Kaynak yokluğu ile arama sonucu yokluğunu ayırın.'),t('Connect a source or clear filters.','Kaynak bağlayın veya filtreleri temizleyin.')],[t('Stale / partial error','Eski veri / kısmi hata'),t('Keep good data visible; name the failed section and last update.','Sağlam veriyi koruyun; başarısız bölümü ve son güncellemeyi belirtin.'),t('Retry the affected section only.','Sadece etkilenen bölümü tekrar deneyin.')]].map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>'),'States','review-table')}`))}
<div class="grid2"><section class="panel"><div class="panel-body form-section">${appearance()}</div></section>${panel(t('Preview controls','Önizleme kontrolleri'),t('Explore role, data and licensing states without connecting to any server.','Herhangi bir sunucuya bağlanmadan rol, veri ve lisans durumlarını keşfedin.'),panelBody(`<div class="field"><label for="preview-role">${t('Preview role','Önizleme rolü')}</label><select id="preview-role" data-change="role">${[['admin',t('Administrator','Yönetici')],['operator',t('Operator','Operatör')],['auditor',t('Auditor','Denetçi')]].map(([v,l])=>`<option value="${v}" ${state.role===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="preview-license">${t('License state','Lisans durumu')}</label><select id="preview-license" data-change="license"><option value="active" ${state.license==='active'?'selected':''}>${t('Active','Etkin')}</option><option value="locked" ${state.license==='locked'?'selected':''}>${t('Locked · external changes paused','Kilitli · dış değişiklikler duraklatıldı')}</option></select></div><span class="field-label">${t('Certificate list state','Sertifika listesi durumu')}</span><div class="state-options">${[['ready',t('Populated','Dolu')],['empty',t('Empty','Boş')],['loading',t('Loading','Yükleniyor')],['error',t('Error','Hata')]].map(([v,l])=>`<button class="state-option ${state.sampleState===v?'active':''}" data-action="set-sample-state" data-value="${v}">${l}</button>`).join('')}</div><div class="flex wrap mt24">${link(t('See certificates','Sertifikaları gör'),'certificates','ArrowRight','btn')}${link(t('Sign-in screen','Giriş ekranı'),'login','LogOut','btn')}${link(t('Setup walkthrough','Kurulum akışı'),'setup','CirclePlay','btn')}</div>`))}</div>
${panel(t('06 / Production handoff','06 / Ürüne uygulama'),t('Extend the existing React and Mantine stack. Preserve its safety model.','Mevcut React ve Mantine yapısını genişletin. Güvenlik modelini koruyun.'),panelBody(rules([[t('Theme layer first','Önce tema katmanı'),t('Move semantic colors into CSS variables. Replace light-only default and hardcoded black/gray overrides. Retain the CSP nonce and translated scroll-region labels.','Anlamsal renkleri CSS değişkenlerine taşıyın. Açık moda sabitlemeyi ve doğrudan siyah/gri geçersiz kılmalarını değiştirin. CSP nonce ve çevrilen kaydırma alanı etiketlerini koruyun.')],[t('Reusable resource patterns','Yeniden kullanılabilir kaynak kalıpları'),t('Build PageHeader, ResourceTable, StatusBadge, FactList, OperationTimeline and EmptyState around existing components. Keep URL-based filters, cursor pagination and saved views.','Mevcut bileşenlerin çevresinde PageHeader, ResourceTable, StatusBadge, FactList, OperationTimeline ve EmptyState oluşturun. URL filtrelerini, imleçli sayfalamayı ve kayıtlı görünümleri koruyun.')],[t('Retain operational contracts','Operasyon sözleşmelerini koruyun'),t('Continue using deploymentView, actions_allowed, server RBAC and step-up. Do not compute an operation’s success or eligibility from its visual state.','deploymentView, actions_allowed, sunucu RBAC ve step-up yapısını kullanmaya devam edin. İşlem başarısını veya yetkisini görsel durumdan hesaplamayın.')],[t('Validate both themes and both languages','İki tema ve iki dili doğrulayın'),t('Check real screens at 1440, 1024, 768 and 390 px; keyboard and screen-reader flows; auth, license lock, stale responses and partial rollback. Browser visual QA remains to be completed for this prototype.','Gerçek ekranları 1440, 1024, 768 ve 390 pikselde; klavye ve ekran okuyucuyla; giriş, lisans kilidi, eski yanıtlar ve kısmi geri alma durumlarında test edin. Bu prototipin tarayıcı görsel kontrolü henüz tamamlanmadı.')]])))}
</div>${footer()}`}
export function reviewPage(){const screens=[['overview','LayoutDashboard',t('Operations overview','Operasyon özeti'),t('Risk-first dashboard + assurance view','Risk öncelikli dashboard ve güvence görünümü')],['certificates','FileKey2',t('Certificate inventory','Sertifika envanteri'),t('Expiry filters, saved views, export, detail','Bitiş filtreleri, kayıtlı görünüm, dışa aktarma, detay')],['certificates/crt-2','Network',t('Certificate detail','Sertifika detayı'),t('Source, validity, locations, deployment','Kaynak, geçerlilik, konumlar, dağıtım')],['servers','Server',t('Servers & identities','Sunucular ve kimlikler'),t('Connectivity, host-key review, discovery','Bağlantı, sunucu anahtarı incelemesi, keşif')],['key-vaults','Cloud','Azure Key Vault',t('Versions, website bindings, access boundaries','Sürümler, web sitesi bağlantıları, erişim sınırları')],['ssh-keys','KeyRound',t('SSH key inventory','SSH anahtar envanteri'),t('Ownership, strength, managed/discovered','Sahiplik, güç, yönetilen/keşfedilen ayrımı')],['rotations','RotateCw',t('Rotation policies','Rotasyon ilkeleri'),t('Schedule, overlap, per-location results','Zamanlama, geçiş, konum bazlı sonuçlar')],['deployments','Rocket',t('Deployment history','Dağıtım geçmişi'),t('Steps, rollback, recovery and evidence','Adımlar, geri alma, kurtarma ve kanıt')],['audit','ScrollText',t('Audit trail','Denetim kaydı'),t('Actor, resource, result, integrity','Kişi, kaynak, sonuç, bütünlük')],['users','Users',t('People & access','Kişiler ve erişim'),t('Admin, operator, auditor + MFA','Yönetici, operatör, denetçi ve MFA')],['license','CreditCard',t('License & continuity','Lisans ve süreklilik'),t('Target limits and graceful lock states','Hedef sınırları ve güvenli kilit durumları')],['settings','Settings2',t('Administration','Yönetim'),t('Backups, SSO, HTTPS, alerts and forwarding','Yedekler, SSO, HTTPS, uyarılar ve yönlendirme')],['account','UserRound',t('Personal account','Kişisel hesap'),t('Appearance, language, recovery, tokens','Görünüm, dil, kurtarma, belirteçler')],['login','Fingerprint',t('Sign-in & MFA','Giriş ve MFA'),t('Local credentials and OIDC','Yerel kimlik bilgileri ve OIDC')],['setup','CirclePlay',t('First-run setup','İlk kurulum'),t('Guided configuration with trust checkpoints','Doğrulama adımlarıyla rehberli yapılandırma')]];
return title(t('Understand first. Design second.','Önce anla. Sonra tasarla.'),t('The reasoning behind this redesign, grounded in the Alice repository.','Bu yeniden tasarımın Alice kaynak koduna dayanan gerekçeleri.'),link(t('Open repository','Kaynak kodu aç'),'','','btn').replace('href="#/"','href="https://github.com/erenmeren/alice" target="_blank" rel="noopener"'))+
`<div class="guide-callout mb16"><strong>${t('Review snapshot','İnceleme referansı')}</strong> · <code>main @ 44521f52</code> · 12 Oct 2026<br><span class="small">${t('Reviewed product documentation, the 23 page entry points, navigation, theme, dashboard contracts and key operational components. The current visual assessment is based on source code; the original application was not run in a browser.','Ürün dokümanları, 23 sayfa giriş noktası, navigasyon, tema, dashboard sözleşmeleri ve temel operasyon bileşenleri incelendi. Mevcut görsel değerlendirme kaynak koda dayanır; asıl uygulama tarayıcıda çalıştırılmadı.')}</span></div>
<div class="stack">${panel(t('What Alice actually does','Alice gerçekte ne yapıyor?'),'',panelBody(`<p>${t('Alice is a self-hosted TLS certificate and SSH key management product for infrastructure teams. It discovers Nginx certificates, tracks Azure Key Vault versions, deploys certificate replacements with verification and rollback, and rotates managed Linux SSH keys. It supports offline deployment, EN/TR, mandatory local-account TOTP, OIDC, role-based access, encrypted backups and signed annual licenses.','Alice, altyapı ekipleri için kurum içinde çalışan TLS sertifikası ve SSH anahtarı yönetim ürünüdür. Nginx sertifikalarını keşfeder, Azure Key Vault sürümlerini izler, doğrulama ve geri alma ile sertifika dağıtır ve yönetilen Linux SSH anahtarlarını döndürür. Çevrimdışı kurulum, EN/TR, yerel hesaplarda zorunlu TOTP, OIDC, role dayalı erişim, şifreli yedekler ve imzalı yıllık lisanslar desteklenir.')}</p><div class="scope-tags">${['Nginx','Linux SSH','Azure Key Vault','Self-hosted','EN / TR','RBAC + MFA','Offline licensing'].map(x=>badge(x)).join('')}</div><div class="mt24">${sourceRef('docs/README.md')}</div>`))}
${panel(t('Why the current interface feels generic','Mevcut arayüz neden sıradan hissediyor?'),t('Concrete observations from the implementation.','Uygulamadan somut gözlemler.'),`<div style="padding-top:20px">${table([t('Observed implementation','Gözlenen uygulama'),t('User impact','Kullanıcıya etkisi'),t('Design response','Tasarım karşılığı')],[
 [t('A flat list of 12 sidebar destinations.','Kenar çubuğunda düz 12 bağlantı listesi.')+'<br>'+sourceRef('web/src/layout/AppLayout.tsx'),t('Daily operations and administration compete for attention.','Günlük operasyonla yönetim aynı alanda yarışıyor.'),t('Group inventory, operations and administration. Move personal controls to the account area.','Envanter, operasyon ve yönetimi grupla. Kişisel kontrolleri hesap alanına taşı.')],
 [t('Nine similarly framed dashboard widgets in a 1/2/3-column grid.','1/2/3 sütunlu düzende benzer çerçeveli dokuz dashboard bileşeni.')+'<br>'+sourceRef('web/src/pages/DashboardPage.tsx'),t('Risk, backups and licensing receive similar emphasis.','Riskler, yedekleme ve lisans benzer ağırlıkta.'),t('Put deadlines and unresolved operations first. Add a separate assurance view using the same permitted data.','Son tarihleri ve çözülmemiş işlemleri öne al. İzin verilen verilerle ayrı güvence görünümü oluştur.')],
 [t('Indigo defaults, light-only provider, hardcoded black/gray foregrounds.','Indigo varsayılanları, açık moda sabit sağlayıcı, doğrudan siyah/gri metinler.')+'<br>'+sourceRef('web/src/theme.ts')+'<br>'+sourceRef('web/src/ThemeProvider.tsx'),t('A generic toolkit look; dark mode cannot be added safely by changing the background alone.','Genel arayüz kütüphanesi hissi; sadece arka planı değiştirerek koyu mod eklenemez.'),t('Semantic light/dark tokens, a distinct brand accent, self-hosted variable type.','Anlamsal açık/koyu tokenlar, belirgin marka rengi, yerel değişken fontlar.')],
 [t('Resource detail pages are long vertical lists of facts and tables.','Kaynak detayları uzun dikey bilgi ve tablo listeleri.')+'<br>'+sourceRef('web/src/pages/CertificateDetailPage.tsx'),t('The relationship between source, certificate and destination is not immediately visible.','Kaynak, sertifika ve hedef ilişkisi ilk bakışta görünmüyor.'),t('Add a source-to-location view, a concise fact panel and a clear next action.','Kaynak–konum görünümü, özlü bilgi paneli ve net sonraki eylem ekle.')],
 [t('Strong existing safety semantics and accessibility fixes.','Güçlü mevcut güvenlik anlamları ve erişilebilirlik düzeltmeleri.')+'<br>'+sourceRef('web/src/api/deployments.ts'),t('A superficial restyle could hide an unknown or partially recovered outcome.','Yüzeysel görsel değişim bilinmeyen veya kısmen kurtarılmış sonucu gizleyebilir.'),t('Preserve operation distinctions, focus rings, server-derived permissions and error explanations.','İşlem ayrımlarını, odak çizgilerini, sunucu izinlerini ve hata açıklamalarını koru.')]
 ].map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>'),'Source review','review-table')}</div>`)}
<div class="compare-grid"><section class="compare-card"><div class="eyebrow">${t('EXISTING STRUCTURE','MEVCUT YAPI')}</div><h2 class="mt16">${t('Feature-first navigation','Özellik merkezli gezinme')}</h2><ul><li>${t('Flat menu and generic page templates','Düz menü ve genel sayfa kalıpları')}</li><li>${t('Similar emphasis for every dashboard widget','Tüm dashboard bileşenlerinde benzer vurgu')}</li><li>${t('Long detail pages with limited visual grouping','Sınırlı görsel gruplamayla uzun detaylar')}</li><li>${t('Light-only theme overrides','Açık moda özel tema ayarları')}</li></ul></section><section class="compare-card after"><div class="eyebrow">${t('PROPOSED DIRECTION','ÖNERİLEN YÖN')}</div><h2 class="mt16">${t('A workspace built around decisions','Kararlar etrafında kurulan çalışma alanı')}</h2><ul><li>${t('What needs attention, then what is affected','Önce ilgi bekleyen, sonra etkilenen kaynaklar')}</li><li>${t('Source, destination and verification stay connected','Kaynak, hedef ve doğrulama bir arada')}</li><li>${t('Consistent inventory and operation patterns','Tutarlı envanter ve işlem kalıpları')}</li><li>${t('Light / dark / system with role-aware content','Açık / koyu / sistem ve role göre içerik')}</li></ul></section></div>
${panel(t('Product boundaries preserved','Korunan ürün sınırları'),'',panelBody(rules([[t('No invented security score','Uydurma güvenlik puanı yok'),t('Show observed facts, freshness and missing evidence. Never label an entire infrastructure “secure” because it is reachable.','Gözlenen bilgiyi, güncelliğini ve eksik kanıtı gösterin. Erişilebilir olduğu için tüm altyapıyı “güvenli” etiketlemeyin.')],[t('No unsupported integrations','Desteklenmeyen entegrasyon yok'),t('Do not imply ACME, Kubernetes, Apache/IIS, multi-tenant workspaces or Azure key rotation. These are outside the reviewed v1 scope.','ACME, Kubernetes, Apache/IIS, çok kiracılı çalışma alanları veya Azure anahtar rotasyonu vaat etmeyin. Bunlar incelenen v1 kapsamı dışındadır.')],[t('Honest renewal language','Doğru yenileme dili'),t('Alice deploys renewed Key Vault certificates or user-supplied certificates. A generic “renew everything” button would promise more than the product does.','Alice, Key Vault’ta yenilenmiş veya kullanıcı tarafından sağlanan sertifikaları dağıtır. “Her şeyi yenile” düğmesi mevcut üründen fazlasını vaat eder.')],[t('Roles are operational boundaries','Roller operasyon sınırlarıdır'),t('Admin manages identities, policies and credentials. Operator handles allowed certificate/key operations but cannot read audit records. Auditor reads and exports. Sensitive actions retain step-up.','Yönetici kimlikleri, ilkeleri ve yetki bilgilerini yönetir. Operatör izinli sertifika/anahtar işlemlerini yapar; denetim kaydını okuyamaz. Denetçi okur ve dışa aktarır. Hassas işlemlerde step-up korunur.')],[t('License lock preserves continuity','Lisans kilidi sürekliliği korur'),t('External mutations pause; inventory, exports, audit and backups remain. Never delete or revoke resources because the license expired.','Dış değişiklikler durur; envanter, dışa aktarma, denetim ve yedekler erişilebilir kalır. Lisans sona erdiği için kaynak silinmez veya iptal edilmez.')]])))}
${panel(t('Designed screen map','Tasarlanan ekran haritası'),t('Explore the main journeys and their detail screens.','Ana akışları ve detay ekranlarını keşfedin.'),panelBody(`<div class="coverage-grid">${screens.map(([path,ico,name,desc])=>`<a class="coverage-card" href="#/${path}">${icon(ico)}<h3>${name}</h3><p>${desc}</p></a>`).join('')}</div>`))}
${panel(t('API and implementation mapping','API ve uygulama eşleştirmesi'),t('Separate presentational changes from new data requirements.','Sunum değişikliklerini yeni veri gereksinimlerinden ayırın.'),`<div style="padding-top:18px">${table([t('Proposed surface','Önerilen görünüm'),t('Existing source','Mevcut kaynak'),t('Implementation note','Uygulama notu')],[[t('Overview and assurance','Genel bakış ve güvence'),'<code>GET /dashboard/summary</code><br><code>GET /dashboard/expiring</code><br><code>GET /alerts</code>',t('Use the role-filtered fields. Never sum cumulative expiry counts as independent buckets.','Role göre filtrelenen alanları kullanın. Birikimli bitiş sayılarını bağımsız kümeler gibi toplamayın.')],[t('60-day histogram','60 günlük histogram'),'<code>certificates.not_after</code><br><code>GET /dashboard/expiring</code>',t('The demo bins complete synthetic data. Production needs all relevant rows or a server aggregate; do not build the chart from only the first 10 results.','Demo tam örnek veriyi gruplar. Üretimde ilgili tüm satırlar veya sunucu özeti gerekir; grafiği ilk 10 sonuçtan üretmeyin.')],[t('Source-to-location view','Kaynak–konum görünümü'),'<code>CertificateDetail.locations</code><br><code>bindings / Key Vault versions</code>',t('Use location and binding IDs. Grouping is a visual presentation of existing relationships.','Konum ve bağlantı kimliklerini kullanın. Gruplama mevcut ilişkilerin görsel sunumudur.')],[t('Operation timeline','İşlem zaman çizelgesi'),'<code>DeploymentDetail.steps</code><br><code>deploymentView()</code>',t('Reuse outcome and recovery logic. Distinguish remote, local and skipped verification.','Sonuç ve kurtarma mantığını kullanın. Uzak, yerel ve atlanan doğrulamayı ayırın.')],[t('Rotation screen','Rotasyon ekranı'),'<code>/rotation/policies</code><br><code>/rotation/runs/{id}</code>',t('Standalone navigation is new; capabilities already exist. Buttons must follow actions_allowed.','Ayrı menü yeni; yetenekler mevcut. Düğmeler actions_allowed verisini izlemeli.')],[t('Global search','Genel arama'),t('No unified search endpoint found in the reviewed routes.','İncelenen rotalarda birleşik arama uç noktası bulunmadı.'),t('Prototype searches local samples. Production requires a scoped aggregation endpoint or bounded client search; enforce RBAC.','Prototip yerel örneklerde arar. Üretimde kapsamlı uç nokta veya sınırlandırılmış istemci araması gerekir; RBAC uygulayın.')],[t('Dark mode','Koyu mod'),'<code>ThemeProvider.tsx</code><br><code>theme.ts / theme.css</code>',t('Keep Mantine and CSP support. Adapt semantic colors and remove light-only overrides; test contrast in both modes.','Mantine ve CSP desteğini koruyun. Anlamsal renkleri uyarlayın, açık moda özel ayarları kaldırın ve iki modda kontrastı test edin.')]].map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>'),'API map','review-table')}</div>`)}
${panel(t('Deliverable and verification scope','Teslimat ve doğrulama kapsamı'),'',panelBody(`<p>${t('This is an interactive design prototype built from a source review, not a replacement production backend. The original GitHub repository has not been modified. Sample interactions run locally in the browser; only theme, language, density and saved filter preferences are retained. No server credentials, private keys or external integrations are used.','Bu, kaynak incelemesine dayanan etkileşimli tasarım prototipidir; üretim backend’inin yerini almaz. Asıl GitHub deposu değiştirilmedi. Örnek etkileşimler tarayıcıda yerel çalışır; yalnızca tema, dil, yoğunluk ve kayıtlı filtre tercihleri saklanır. Sunucu kimlik bilgileri, özel anahtarlar veya dış entegrasyonlar kullanılmaz.')}</p><p class="small mt16">${t('Validation covers JavaScript syntax, DOM route rendering, key interactions, localization rendering, role restrictions and token contrast. Browser-based visual and real-backend integration checks remain pending.','Doğrulama; JavaScript sözdizimi, DOM rota oluşturma, temel etkileşimler, yerelleştirilmiş oluşturma, rol kısıtları ve token kontrastını kapsar. Tarayıcı görsel kontrolü ve gerçek backend entegrasyon testleri bekliyor.')}</p><div class="mt24 flex wrap gap16">${sourceRef('docs/authz-matrix.md')}${sourceRef('web/src/api/phase7.ts')}${sourceRef('web/src/api/rotation.ts')}${sourceRef('docs/licensing.md')}</div>`))}
</div>${footer()}`}
